import{_ as d,a as t,b as o}from"./chunks/5elements-2.75774190.js";import{D as c}from"./chunks/donate.3a95be8c.js";import{o as a,c as r,O as l,X as e}from"./chunks/framework.7fab6bae.js";import"./chunks/wcpay.d0e1a780.js";const i=e('<h1 id="紫微斗数基础" tabindex="-1">자미두수 기초（紫微斗數基礎） <a class="header-anchor" href="#紫微斗数基础" aria-label="Permalink to &quot;자미두수 기초（紫微斗數基礎）   {#紫微斗数基础}&quot;">​</a></h1><h2 id="前言" tabindex="-1">서문 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;서문   {#前言}&quot;">​</a></h2><p>자미두수（紫微斗數）는 <code>사람</code>과 <code>외부 환경</code>의 관계를 살펴보는 학문입니다. 이 사이트의 접근은 전통적인 학습 방식과 다를 수 있습니다. 이미 공부한 적이 있다면 기존 지식과 다른 설명도 있으므로, 자신의 이해와 비교하며 신중하게 읽어 주세요. 이 사이트는 초보자가 원리를 이해하고 재미를 발견할 수 있도록 쉬운 입문 설명을 제공하는 것이 목적입니다. 잘못된 점은 알려 주세요.</p><blockquote><p><em>이 연재는 저자가 직접 쓴 글입니다. 다른 곳에 옮길 때는 출처를 밝혀 주세요.</em></p></blockquote><div class="tip custom-block"><p class="custom-block-title">팁</p><p>이 사이트는 논리적인 추론을 중심으로 설명합니다. 신비주의적 접근을 선호하는 분은 이 차이를 고려해 읽어 주세요.</p></div>',5),p=e('<h2 id="紫微斗数能干嘛" tabindex="-1">자미두수（紫微斗數）는 무엇을 할 수 있나요? <a class="header-anchor" href="#紫微斗数能干嘛" aria-label="Permalink to &quot;자미두수（紫微斗數）는 무엇을 할 수 있나요?   {#紫微斗数能干嘛}&quot;">​</a></h2><p>많은 독자는 자미두수（紫微斗數）를 고대 중국의 운명을 점치는 기법으로만 알고 있을지 모릅니다. 제 관점에서 이는 오락적인 기능일 뿐 전체는 아닙니다. 명리 해석을 전문으로 하는 분들도 오해하지 않으셨으면 합니다. 자미두수의 역량을 부정하려는 것은 아닙니다. 점술의 의미를 잘 모른 채 미지의 일에 대한 두려움과 불안으로 초자연적인 도움을 찾는 사람도 많습니다. 이 장부터 더 전체적인 내용을 소개하겠습니다. 자미두수는 무엇을 할 수 있을까요?</p><ul><li><p>성격 분석</p><p>전통 명리학이나 심리학의 여러 접근은 성격을 분석하며, MBTI 같은 설문 방식도 그 예입니다. 성격은 단순하고 한쪽 면만 있는 것이 아닙니다. 상대나 상황에 따라 전혀 다른 모습을 보여, 간단한 분류만으로 설명하기 어렵습니다. 자미두수（紫微斗數）는 12개의 <a href="./palace"><code>궁</code>（宮位）</a>으로 여러 측면을 분석하고 분류하여 세밀한 성격 특징을 살펴봅니다.</p><p>성격 분석이 실제 성격과 크게 다르면 바로 멈추세요. 첫 단계가 맞아야 뒤의 해석도 의미가 있습니다. 이런 차이는 왜 생길까요? 다음과 같은 원인을 정리했습니다:</p><ol><li><p>출생 시간 정보의 오류</p><p>출생 시간은 부모가 정확히 기억하지 못할 수 있어 흔한 오류 원인입니다. 하나의 시진은 오늘날의 두 시간에 해당합니다. 3시 무렵처럼 경계에 가까우면 두 가지 명반이 가능하므로, 둘 다 살펴보고 실제 성격이 어느 쪽과 더 맞는지 비교하는 것이 좋습니다.</p><p>출생 시각이 잘못 기록된 경우도 있습니다. 예를 들어 실제로는 2시 54분에 태어났는데 3시 5분으로 기록되면 출생 시진이 달라집니다.</p><p>달력 변환이나 경계 시점을 정하는 기준의 차이로 명반이 달라질 수도 있습니다. 자미두수（紫微斗數）에 쓰는 중국의 농력은 그 자체가 태음태양력입니다. 각 달은 달의 위상 변화를 기준으로 정하고, 절기는 태양의 계절적 변화를 나타냅니다. 따라서 음력 월의 경계와 일부 간지（干支） 계산에서 사용하는 절기 경계를 구분해야 합니다. 절기가 바뀌는 시각이 반드시 자정인 것도 아닙니다. 경계 부근에 태어났다면 날짜 변환과 적용한 명반 작성 규칙을 확인한 뒤 가능한 명반을 비교해야 합니다.</p><p>서머타임 같은 시계 조정으로 출생 시진이 달라질 수도 있습니다. 아래는 중국 본토에서 서머타임을 시행한 기간입니다. 이때 태어났다면 기록된 시각에서 한 시간을 빼야 합니다. 다만 부모님이 이미 보정했을 수 있으므로 먼저 확인하세요. 자세한 내용은 <a href="https://baike.baidu.com/item/%E5%A4%8F%E4%BB%A4%E6%97%B6/1809579" target="_blank" rel="noreferrer"><code>바이두백과사전</code></a>을 참고하세요.</p><table><thead><tr><th>중국 본토의 일광 절약 시간제</th></tr></thead><tbody><tr><td>1986년 5월 4일 ~ 9월 14일 (1986년이 서머타임의 첫해였기 때문에 5월 4일에 시작해서 9월 14일에 끝났습니다)</td></tr><tr><td>1987년 4월 12일 ~ 9월 13일</td></tr><tr><td>1988년 4월 10일 ~ 9월 11일</td></tr><tr><td>1989년 4월 16일 ~ 9월 17일</td></tr><tr><td>1990년 4월 15일 ~ 9월 16일</td></tr><tr><td>1991년 4월 14일 ~ 9월 15일</td></tr></tbody></table><p>다른 국가나 지역의 일광 절약 시간제 시행 시간은 현지 공식 데이터를 참조하세요.</p></li><li><p>명반 해석자의 자미두수（紫微斗數） 이해 수준</p><p>해석자마다 이해 수준이 달라 반대 결론을 낼 수도 있습니다. 출생 시간 정보가 정확하다면 이런 차이를 알아차리기 쉽습니다. 대면 해석에서 상대의 반응을 살피고 유도하는 말에 의존한다면, 자신의 부족함을 인정하지 않으려는 모습일 수 있습니다. 제 실력도 평범하지만 해석이 맞지 않을 때는 솔직하게 받아들입니다. 한 번의 부정확한 경험 때문에 자미두수（紫微斗數） 전체를 포기하지 않으셨으면 합니다. 알고리즘과 문서를 공개한 이유도, 누구나 기초를 갖추고 관심 있는 사람은 더 깊이 연구할 수 있게 하기 위해서입니다.</p></li><li><p>명반 해석자의 설명 능력</p><p>설명하는 능력과 이해하는 방식도 차이를 만들 수 있습니다. 같은 햄릿을 읽어도 해석이 다르고, 작가가 커튼을 파란색으로 묘사한 이유도 사람마다 다르게 봅니다. 마찬가지로 명반 해석자가 전달하려는 내용과 본인이 받아들이는 의미 사이에도 차이가 생깁니다.</p></li></ol></li><li><p>자녀 교육</p><p>부모는 “내 아이를 내가 모르겠나?”라고 생각하기 쉽습니다. 하지만 보이는 것은 성격의 한 면뿐입니다. 24시간 곁에 있으면서 친구나 반 친구들과 어떻게 지내는지, 상대의 역할에 따라 어떤 모습을 보이는지, 부모를 어떻게 생각하는지까지 전부 볼 수는 없습니다. 필자는 아이의 명반으로 이런 면을 살피고, 아이에게 맞는 교육 방법을 찾을 수 있다고 봅니다.</p></li><li><p>진로 계획</p><p>목표가 확고한 사람에게는 도움이 적을 수 있습니다. 하지만 어떤 일이 적성에 맞는지, 대학에서 어떤 전공을 선택할지 모를 때 참고할 수 있습니다. 이후 진로에서 순조롭거나 어려운 시기를 예보처럼 살펴보고 미리 대비하는 데도 쓸 수 있습니다.</p></li><li><p>대화의 소재</p><p>별자리나 MBTI처럼 자미두수（紫微斗數）도 대화의 소재가 될 수 있습니다. 처음 만난 사람과 어색함을 풀고 더 빨리 친해지는 데 도움이 됩니다. 양쪽 모두 어느 정도 알고 있다면 더욱 그렇습니다.</p></li><li><p>배우자 선택</p><p>배우자 선택이라고 하면 사주 궁합을 떠올릴 수 있지만, 여기서 말하는 것은 그 방식이 아닙니다. 소개팅이든 자연스러운 만남이든 정확한 생년월일과 시각을 바로 묻기는 어색합니다. 자미두수（紫微斗數）를 알면 대화와 행동에서 상대의 성요 조합을 대략 짐작해, 어떻게 관계를 맺을지 참고할 수 있습니다. 양쪽 모두 안다면 별자리 이야기처럼 주성（主星）을 이야기하며, 출생 정보를 묻는 어색함 없이 성격과 취향을 빠르게 알아볼 수 있습니다.</p></li></ul><h2 id="术语解释" tabindex="-1">용어 설명 <a class="header-anchor" href="#术语解释" aria-label="Permalink to &quot;용어 설명   {#术语解释}&quot;">​</a></h2><p>자미두수（紫微斗數）에는 전문 용어가 많습니다. 뜻을 알면 다른 사람의 명반 해석을 쉽게 따라갈 수 있습니다. 여러 해석을 접한 뒤 직접 해석해 보아도 좋습니다. 명반을 연구하는 재미를 느낄 수 있도록 자주 쓰는 용어를 하나씩 설명합니다.</p><h3 id="性别阴阳" tabindex="-1"><code>성별과 음양</code>（性別陰陽） <a class="header-anchor" href="#性别阴阳" aria-label="Permalink to &quot;`성별과 음양`（性別陰陽）   {#性别阴阳}&quot;">​</a></h3><p>자미두수（紫微斗數）에서는 <code>양남음녀</code>（陽男陰女）, <code>음남양녀</code>（陰男陽女）라는 표현을 자주 씁니다. 출생 연도의 <code>천간</code>（天干）이 가진 음양（陰陽） 속성과 성별을 조합하면 다음 네 가지로 나뉩니다.</p><ul><li>양년생 남성（陽男）</li><li>양년생 여성（陽女）</li><li>음년생 남성（陰男）</li><li>음년생 여성（陰女）</li></ul><p>성별과 출생 연도의 음양 속성은 일부 계산 결과의 배열 순서에 영향을 줍니다.</p><h3 id="顺行-逆行" tabindex="-1"><code>순행</code> / <code>역행</code> <a class="header-anchor" href="#顺行-逆行" aria-label="Permalink to &quot;`순행` / `역행`   {#顺行-逆行}&quot;">​</a></h3><p>자미두수（紫微斗數）에서 순행은 <code>시계 방향</code>, 역행 또는 역부는 <code>반시계 방향</code>으로 진행하는 것입니다. <code>양남음녀 순행</code>（陽男陰女順行）은 해당 배열을 <code>시계 방향</code>으로 배치하고, <code>음남양녀 역행 또는 역부</code>（陰男陽女逆行或逆部）는 <code>반시계 방향</code>으로 배치하라는 뜻입니다.</p><h3 id="星盘" tabindex="-1"><code>명반</code>（星盤） <a class="header-anchor" href="#星盘" aria-label="Permalink to &quot;`명반`（星盤）   {#星盘}&quot;">​</a></h3><p>자세한 내용은 <a href="./astrolabe">명반 소개（星盤介紹）</a>를 참고하세요.</p><ul><li><p>명반 작성（排盤）</p><p>출생 날짜, 시진（時辰）, 성별을 바탕으로 명반（星盤）을 작성하는 과정입니다.</p></li><li><p>명반 해석</p><p>명반에 담긴 정보를 해석하는 과정입니다.</p></li><li><p>본명반（本命盤）</p><p><code>천반</code>（天盤）이라고도 합니다. 출생 날짜와 시진으로 계산한 명반이며, 그 배치는 고정되어 있습니다.</p></li><li><p>대한반（大限盤）</p><p><code>지반</code>（地盤）이라고도 합니다. 천반（天盤）의 열두 궁이 차례로 중심 역할을 맡으며, 각 궁의 기간은 <code>10년</code>입니다. <code>명궁</code>（命宮）이 <code>첫 번째 대한</code>（第一大限）이고, 그 이후의 대한은 <code>제n대한</code>（第n大限）이라고 부릅니다.</p></li><li><p>유년반（流年盤）</p><p><code>인반</code>（人盤）이라고도 합니다. 대한（大限）은 10년마다 바뀌고 유년（流年）은 <code>매년</code> 바뀝니다. 해당 연도의 <code>지지</code>（地支）가 놓인 궁이 유년 명궁（流年命宮）이 됩니다.</p></li><li><p>천지인 삼재（天地人三才）</p><p><code>본명반</code>（本命盤）, <code>대한반</code>（大限盤）, <code>유년반</code>（流年盤）을 통틀어 부르는 말입니다.</p></li><li><p>격국（格局）</p><p>특정 <code>성요</code>（星曜） 조합은 <code>격국</code>（格局）을 이룹니다. 게임에서 장비의 <code>세트 효과</code>가 일부 능력에 영향을 주듯, 특정 성질에 추가 작용을 줍니다.</p></li></ul><h3 id="宫位" tabindex="-1"><code>궁</code>（宮位） <a class="header-anchor" href="#宫位" aria-label="Permalink to &quot;`궁`（宮位）   {#宫位}&quot;">​</a></h3><p>궁위의 기본 개념은 <a href="./palace">궁위 체계（宮位系統）</a>에서 설명합니다.</p><ul><li><p>궁간（宮干）</p><p>해당 궁에 배정된 <code>천간</code>（天干）을 뜻합니다.</p></li><li><p>본궁（本宮）</p><p>현재 살펴보는 궁입니다. <code>부처</code>（夫妻）궁을 보고 있다면 그 궁이 <code>본궁</code>（本宮）입니다.</p></li><li><p>대궁（對宮）</p><p>대상 궁의 맞은편에 있는 궁으로, <code>대궁 위치</code>（四正位）라고도 합니다.</p></li><li><p>삼합 위치（三合位）</p><p><code>삼재방</code>（三才方） 또는 <code>삼방</code>（三方）이라고도 합니다. <code>본궁</code>（本宮）과, 본궁의 인덱스에 <code>±4</code>를 적용한 두 궁을 함께 가리킵니다.</p></li><li><p>대궁 위치（四正位）</p><p><code>대궁</code>（對宮）이라고도 합니다. <code>본궁</code>（本宮）의 인덱스에 <code>+6</code>을 적용한 위치입니다.</p></li><li><p>삼방사정（三方四正）</p><p><code>삼합 위치</code>（三合位）와 <code>대궁 위치</code>（四正位）를 통틀어 부르는 말입니다.</p></li><li><p>천라（天羅）와 지망（地網）</p><p><code>진</code>（辰）과 <code>술</code>（戌）에 해당하는 두 궁을 뜻합니다. <code>진</code>（辰）은 천라위（天羅位）, <code>술</code>（戌）은 지망위（地網位）입니다. 주역（周易）에서 유래한 개념으로, 진은 <code>천강</code>（天罡）, 술은 <code>하괴</code>（河魁）에 해당합니다. 이 둘은 대육임（大六壬）의 십이신장（十二神將）에도 속합니다. 반드시 외울 내용은 아니며, 관심이 있으면 더 알아보면 됩니다.</p></li><li><p>공궁（空宮）</p><p>해당 궁에 <a href="./major-star">주성（主星）</a>이 없다는 뜻입니다.</p></li><li><p>양옆의 궁（夾宮）</p><p>대상 궁의 바로 앞뒤에 있는 두 궁입니다.</p></li><li><p>천문（天門）과 지문（地門）</p><p>이 개념들은 풍수（風水）에서 유래했습니다.</p><p>천문（天門）은 <code>해궁</code>（亥宮）을 뜻합니다. 후천팔괘（後天八卦）에서 천문은 건괘（乾卦）의 위치에 있습니다. 지지（地支）로 보면 <code>술</code>（戌）과 <code>해</code>（亥）에 해당하지만, 술궁（戌宮）에는 이미 <code>지망위</code>（地網位）라는 의미가 있으므로 천문은 <code>해궁</code>（亥宮）을 가리킵니다. 자미두수（紫微斗數）에는 <code>월랑천문</code>（月朗天門）이라는 유명한 격국이 있습니다. 명궁（命宮）이나 신궁（身宮）이 해궁（亥宮）에 있고 그곳에 <code>태음</code>（太陰）이 있는 배치를 말합니다.</p><p>지문（地門）은 <code>사궁</code>（巳宮）을 뜻하며, 풍수에서는 <code>지호위</code>（地戶位）에 해당합니다. 지호（地戶）는 <code>땅으로 들어가는 문</code>이라는 뜻입니다. 지지（地支）로 보면 지문은 <code>진</code>（辰）과 <code>사</code>（巳）에 해당하지만, 진궁（辰宮）에는 이미 <code>천라위</code>（天羅位）라는 의미가 있으므로 지문은 <code>사궁</code>（巳宮）을 가리킵니다.</p></li><li><p>뇌문（雷門）</p><p><code>묘궁</code>（卯宮）을 뜻합니다. 묘궁이 팔괘（八卦）의 <code>진괘</code>（震） 위치에 있으므로 <code>뇌문</code>（雷門）이라고 부릅니다. 자미두수（紫微斗數）의 유명한 격국인 <code>일조뇌문</code>（日照雷門）은 <code>태양</code>（太陽）과 <code>천량</code>（天梁）이 묘궁（卯宮）에 함께 있는 배치를 뜻합니다.</p></li><li><p>천궁（天宮）과 지궁（地宮）</p><p>천궁（天宮）은 <code>자 지지의 궁</code>（子宮）, 지궁（地宮）은 <code>축궁</code>（丑宮）을 뜻합니다. “天開於子，地闢於丑，人生於寅”는 개념입니다. 래인（來因）궁의 설명에서 이 개념을 사용하므로 여기서 소개합니다. <code>천궁</code>（天宮）, <code>지궁</code>（地宮）은 앞서 설명한 <code>천문</code>（天門）, <code>지문</code>（地門）과 혼동하기 쉽습니다. 서로 다른 개념에서 나온 용어이며 각각의 근거가 있습니다. 프로그래밍에서 서로 다른 변수에 비슷한 이름을 붙인 것처럼 이해하면 됩니다.</p></li></ul><h3 id="星曜" tabindex="-1"><code>성요</code>（星曜） <a class="header-anchor" href="#星曜" aria-label="Permalink to &quot;`성요`（星曜）   {#星曜}&quot;">​</a></h3><p>성요（星曜）는 자미두수（紫微斗數）의 궁을 구성하는 중요한 요소입니다. 자세한 내용은 <a href="./star">성요 체계</a>를 참고하세요.</p><ul><li><p>유요（流曜）</p><p><code>대한</code>（大限）과 <code>유년</code>（流年）에 따라 달라지는 성요입니다.</p></li><li><p>우·가·봉·동궁·동도（遇・加・逢・同宮・同度）</p><p>성요가 같은 궁에 있다는 뜻입니다. 예를 들어 <code>자미</code>（紫微）와 <code>우필</code>（右弼）이 동도한다는 것은 둘 다 같은 궁에 있다는 뜻입니다.</p></li><li><p>회·조·충·부공（會・照・衝・扶拱）</p><p><code>회</code>（會）와 <code>부공</code>（扶拱）은 성요가 대상 궁의 <code>삼방 위치</code>（三方位）에 있음을 뜻합니다. <code>조</code>（照）와 <code>충</code>（衝）은 <code>대궁 위치</code>（四正位）에 있음을 뜻합니다. 어떤 성요와 “회조한다”는 말은 그 성요가 <code>삼방사정</code>（三方四正） 안에 있으면 된다는 뜻입니다.</p></li><li><p>좌·거·수（坐・據・守）</p><p>성요가 어떤 궁 안에 있다는 뜻입니다. 예를 들어 <code>탐랑</code>（貪狼）이 <code>부처</code>（夫妻）궁에 좌한다면 그 궁에 놓여 있다는 뜻입니다.</p></li><li><p>공성·공요（空星・空曜）</p><p><code>지공</code>（地空）, <code>천공</code>（天空）, <code>순공</code>（旬空）, <code>공망</code>（空亡）을 뜻합니다.</p></li><li><p>암요（暗曜）</p><p><a href="./major-star#巨门星"><code>거문</code>（巨門）</a>을 가리킵니다.</p></li><li><p>영성（英星）</p><p><a href="./major-star#破军星"><code>파군</code>（破軍）</a>을 가리킵니다.</p></li><li><p>장성（將星）</p><p><a href="./major-star#七杀星"><code>칠살</code>（七殺）</a>을 가리킵니다.</p></li></ul><h2 id="阴阳五行" tabindex="-1">음양（陰陽）오행（五行） <a class="header-anchor" href="#阴阳五行" aria-label="Permalink to &quot;음양（陰陽）오행（五行）   {#阴阳五行}&quot;">​</a></h2><p>중국 도가 사상에서 <code>음양</code>（陰陽）과 <code>오행</code>（五行）은 기본 개념입니다. 여기서는 자세히 다루지 않고 개념만 소개합니다.</p><ul><li><p>음양（陰陽）</p><p>도가（道家）에서 하나로부터 둘이 생겨난다는 말의 “둘”은 음과 양을 뜻합니다. 이는 사물의 두 측면을 나타냅니다. 예를 들면 다음과 같습니다.</p><ul><li><code>빛</code>은 <code>양</code>, <code>그림자</code>는 <code>음</code>입니다.</li><li><code>남성</code>은 <code>양</code>, <code>여성</code>은 <code>음</code>입니다.</li><li><code>양전하</code>는 <code>양</code>이고, <code>음전하</code>는 <code>음</code>입니다.</li></ul><p>따라서 음양（陰陽）은 상대적인 개념입니다. 만물이 서로 보완하고 복과 화가 서로 의지한다는 뜻입니다. 우리가 추구하는 것은 그 사이의 균형이며, 지나침과 부족함을 피하는 것입니다. <code>양</code>은 대체로 강하고 뜨거운 느낌을 주고, <code>음</code>은 부드럽고 내향적인 느낌을 줍니다.</p></li><li><p>오행（五行）</p><p>문화마다 <code>원소</code>를 설명하는 방식이 다릅니다. 고대 그리스에서는 <code>토</code>, <code>바람</code>, <code>수</code>, <code>화</code>의 네 원소로 설명했습니다.</p><img src="'+d+'" alt="four elements" width="300"><p>고대 인도의 <code>다섯 원소</code>에는 고대 그리스의 네 가지 원소에 <code>공간</code>이라는 원소가 더해집니다. 따라서 <code>토</code>, <code>바람</code>, <code>수</code>, <code>화</code>, <code>공간</code>으로 이루어집니다.</p><img src="'+t+'" alt="five elements" width="300"><p>중국의 <code>오행</code>（五行）은 다른 원소 체계와 공통점도 있고 차이도 있습니다. <code>오행</code>（五行）은 <code>수</code>, <code>목</code>, <code>금</code>, <code>토</code>, <code>화</code>입니다. 금·목·수·화·토 순서가 더 익숙할 수 있지만, 여기서는 자미두수（紫微斗數）의 <a href="#五行局">오행국（五行局）</a>에 맞춰 나열했습니다.</p><img src="'+o+'" alt="five elements" width="300"></li></ul><h2 id="天干地支" tabindex="-1">천간과 지지（天干地支） <a class="header-anchor" href="#天干地支" aria-label="Permalink to &quot;천간과 지지（天干地支）   {#天干地支}&quot;">​</a></h2><p>중국 전통 문화에서 <code>간지 기년법</code>（干支紀年）은 수학의 사칙연산이나 영어의 26개 알파벳처럼 중요한 기초 지식입니다. 자미두수（紫微斗數）에서는 명반（星盤） 전체의 배치를 <code>천간</code>（天干）과 <code>지지</code>（地支）를 기준으로 계산하므로, 기본 개념으로 익혀 두어야 합니다.</p><h3 id="十天干" tabindex="-1">십천간（十天干） <a class="header-anchor" href="#十天干" aria-label="Permalink to &quot;십천간（十天干）   {#十天干}&quot;">​</a></h3><p>십천간（十天干）은 자미두수（紫微斗數）에서 중요하고 유용한 <code>사화</code>（四化）를 정합니다. 자세한 내용은 <a href="./mutagen">사화성（四化星）</a>을 참고하세요.</p><table><thead><tr><th>이름</th><th>오행（五行）</th><th>음양（陰陽）</th></tr></thead><tbody><tr><td>갑（甲）</td><td>🪵 목</td><td>🌕 양</td></tr><tr><td>을（乙）</td><td>🪵 목</td><td>🌑 음</td></tr><tr><td>병（丙）</td><td>🔥 화</td><td>🌕 양</td></tr><tr><td>정（丁）</td><td>🔥 화</td><td>🌑 음</td></tr><tr><td>무（戊）</td><td>⛰️ 토</td><td>🌕 양</td></tr><tr><td>기（己）</td><td>⛰️ 토</td><td>🌑 음</td></tr><tr><td>경（庚）</td><td>🪙 금</td><td>🌕 양</td></tr><tr><td>신（辛）</td><td>🪙 금</td><td>🌑 음</td></tr><tr><td>임（壬）</td><td>🌊 수</td><td>🌕 양</td></tr><tr><td>계（癸）</td><td>🌊 수</td><td>🌑 음</td></tr></tbody></table><h3 id="十二地支" tabindex="-1">십이지지（十二地支） <a class="header-anchor" href="#十二地支" aria-label="Permalink to &quot;십이지지（十二地支）   {#十二地支}&quot;">​</a></h3><p>지지（地支）는 자미두수（紫微斗數） 궁 체계의 고정된 위치를 정합니다. 학교가 지어진 뒤 각 학년과 반의 위치가 고정되는 것과 같습니다. 반면 <code>명궁</code>（命宮）의 위치는 사람에 따라 다릅니다. 입학할 때 1반이나 10반에 배정되는 것에 비유할 수 있습니다. 열두 궁에서 지지의 위치는 아래 표와 같습니다.</p><table class="astrolabe"><tr><td>사（巳）<code>3</code></td><td>오（午）<code>4</code></td><td>미（未）<code>5</code></td><td>신（申）<code>6</code></td></tr><tr><td>진（辰）<code>2</code></td><td class="center-palace" rowspan="2" colspan="2">중궁</td><td>유（酉）<code>7</code></td></tr><tr><td>묘（卯）<code>1</code></td><td>술（戌）<code>8</code></td></tr><tr><td>인（寅）<code>0</code></td><td>축（丑）<code>11</code></td><td>자（子）<code>10</code></td><td>해（亥）<code>9</code></td></tr></table><p>천간（天干）처럼 십이지지（十二地支）에도 음양（陰陽）과 오행（五行）의 구분이 있습니다.</p><table><thead><tr><th>이름</th><th>오행（五行）</th><th>음양（陰陽）</th></tr></thead><tbody><tr><td>자（子）</td><td>🌊 수</td><td>🌕 양</td></tr><tr><td>축（丑）</td><td>⛰️ 토</td><td>🌑 음</td></tr><tr><td>인（寅）</td><td>🪵 목</td><td>🌕 양</td></tr><tr><td>묘（卯）</td><td>🪵 목</td><td>🌑 음</td></tr><tr><td>진（辰）</td><td>⛰️ 토</td><td>🌕 양</td></tr><tr><td>사（巳）</td><td>🔥 화</td><td>🌑 음</td></tr><tr><td>오（午）</td><td>🔥 화</td><td>🌕 양</td></tr><tr><td>미（未）</td><td>⛰️ 토</td><td>🌑 음</td></tr><tr><td>신（申）</td><td>🪙 금</td><td>🌕 양</td></tr><tr><td>유（酉）</td><td>🪙 금</td><td>🌑 음</td></tr><tr><td>술（戌）</td><td>⛰️ 토</td><td>🌕 양</td></tr><tr><td>해（亥）</td><td>🌊 수</td><td>🌑 음</td></tr></tbody></table><h4 id="地支六合" tabindex="-1">지지 육합（地支六合） <a class="header-anchor" href="#地支六合" aria-label="Permalink to &quot;지지 육합（地支六合）   {#地支六合}&quot;">​</a></h4><p><code>결합</code>（合）에는 <code>서로 돕는 관계</code>라는 뜻이 있으며, 그 도움은 <code>비밀리에</code> 이루어집니다. 여기서는 지지（地支）를 깊이 다루지 않습니다. 뒤에서 <a href="./palace#暗合宫">암합궁（暗合宮）</a>을 설명할 때 필요한 육합（六合）을 아래에 정리합니다.</p><ul><li><code>자</code>（子）와 <code>축</code>（丑）은 합하여 <code>⛰️토</code>로 변화합니다.</li><li><code>인</code>（寅）과 <code>해</code>（亥）는 합하여 <code>🪵목</code>으로 변화합니다.</li><li><code>묘</code>（卯）와 <code>술</code>（戌）은 합하여 <code>🔥화</code>로 변화합니다.</li><li><code>진</code>（辰）과 <code>유</code>（酉）는 합하여 <code>🪙금</code>으로 변화합니다.</li><li><code>사</code>（巳）와 <code>신</code>（申）은 합하여 <code>🌊수</code>로 변화합니다.</li><li><code>오</code>（午）와 <code>미</code>（未）는 합하여 <code>⛰️토</code>로 변화합니다.</li></ul><h4 id="地支三合局" tabindex="-1">지지 삼합국（地支三合局） <a class="header-anchor" href="#地支三合局" aria-label="Permalink to &quot;지지 삼합국（地支三合局）   {#地支三合局}&quot;">​</a></h4><p>육합（六合）처럼 삼합의 <code>결합</code>（合）도 서로 돕는 관계입니다. 육합의 도움이 <code>비밀리에</code> 이루어진다면, 삼합은 드러나게 돕습니다. 여기서는 <a href="./palace#三方四正">삼방사정（三方四正）</a>을 설명할 때 필요한 지지（地支） 삼합국만 소개합니다.</p><ul><li><code>신</code>（申）, <code>자</code>（子）, <code>진</code>（辰）은 합하여 <code>🌊수</code>국을 이룹니다.</li><li><code>해</code>（亥）, <code>묘</code>（卯）, <code>미</code>（未）는 합하여 <code>🪵목</code>국을 이룹니다.</li><li><code>인</code>（寅）, <code>오</code>（午）, <code>술</code>（戌）은 합하여 <code>🔥화</code>국을 이룹니다.</li><li><code>사</code>（巳）, <code>유</code>（酉）, <code>축</code>（丑）은 합하여 <code>🪙금</code>국을 이룹니다.</li></ul><h4 id="地支六冲" tabindex="-1">지지 육충（地支六衝） <a class="header-anchor" href="#地支六冲" aria-label="Permalink to &quot;지지 육충（地支六衝）   {#地支六冲}&quot;">​</a></h4><p><code>충</code>（衝）은 충돌을 뜻하며, 조화를 이루려면 많은 힘이 필요한 관계입니다. 지지 육충（地支六沖）은 <a href="./palace#三方四正">삼방사정（三方四正）</a>을 설명할 때 사용합니다.</p><ul><li><code>자</code>（子）와 <code>오</code>（午）는 서로 충합니다.</li><li><code>묘</code>（卯）와 <code>유</code>（酉）는 서로 충합니다.</li><li><code>인</code>（寅）과 <code>신</code>（申）은 서로 충합니다.</li><li><code>사</code>（巳）와 <code>해</code>（亥）는 서로 충합니다.</li><li><code>진</code>（辰）과 <code>술</code>（戌）은 서로 충합니다.</li><li><code>축</code>（丑）과 <code>미</code>（未）는 서로 충합니다.</li></ul><h2 id="十二时辰" tabindex="-1">열두 시진 <a class="header-anchor" href="#十二时辰" aria-label="Permalink to &quot;열두 시진   {#十二时辰}&quot;">​</a></h2><p>중국 전통 시간법은 하루를 <code>열두 시진</code>（十二時辰）으로 나누며, 한 시진은 오늘날의 두 시간에 해당합니다. <code>자시</code>는 <code>23:00~01:00</code>으로 날짜의 경계를 지나므로 특별합니다. 그래서 <code>조자시</code>와 <code>만자시</code>로 구분합니다. 각 시진의 시간대는 다음과 같습니다:</p><table><thead><tr><th>이름</th><th>시간대</th></tr></thead><tbody><tr><td>조자시</td><td>00:00～01:00</td></tr><tr><td>축시</td><td>01:00～03:00</td></tr><tr><td>인시</td><td>03:00～05:00</td></tr><tr><td>묘시</td><td>05:00～07:00</td></tr><tr><td>진시</td><td>07:00～09:00</td></tr><tr><td>사시</td><td>09:00～11:00</td></tr><tr><td>오시</td><td>11:00～13:00</td></tr><tr><td>미시</td><td>13:00～15:00</td></tr><tr><td>신시</td><td>15:00～17:00</td></tr><tr><td>유시</td><td>17:00～19:00</td></tr><tr><td>술시</td><td>19:00～21:00</td></tr><tr><td>해시</td><td>21:00～23:00</td></tr><tr><td>만자시</td><td>23:00～00:00</td></tr></tbody></table><h2 id="五行局" tabindex="-1">오행국（五行局） <a class="header-anchor" href="#五行局" aria-label="Permalink to &quot;오행국（五行局）   {#五行局}&quot;">​</a></h2><p>오행국（五行局）은 자미두수（紫微斗數）에서 첫 대한（大限）이 시작되는 나이를 정하며, <code>육십갑자 납음</code>（六十甲子納音）에서 유래합니다. 이 사이트에서는 <code>육십 납음</code>（六十納音） 자체를 다루지 않으므로 관심이 있으면 따로 공부해 보세요. 이름에 들어가는 숫자가 시작 나이입니다. 수이국（水二局）은 <code>2</code>세, 토오국（土五局）은 <code>5</code>세에 시작합니다. 여기서는 이 점을 알면 충분합니다. 오행국은 다음 다섯 가지입니다:</p><ul><li>🌊 <code>수이국</code>（水二局）</li><li>🪵 <code>목삼국</code>（木三局）</li><li>🪙 <code>금사국</code>（金四局）</li><li>⛰️ <code>토오국</code>（土五局）</li><li>🔥 <code>화육국</code>（火六局）</li></ul>',48),k=JSON.parse('{"title":"자미두수 입문: 기초 지식과 용어","description":"자미두수가 무엇인지 소개하고 명반을 읽는 데 필요한 기초 개념과 용어를 설명합니다.","frontmatter":{"title":"자미두수 입문: 기초 지식과 용어","outline":"deep","description":"자미두수가 무엇인지 소개하고 명반을 읽는 데 필요한 기초 개념과 용어를 설명합니다.","head":[["link",{"rel":"canonical","href":"https://iztro.com/ko_KR/learn/basis"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://iztro.com/learn/basis"}],["link",{"rel":"alternate","hreflang":"zh-TW","href":"https://iztro.com/zh_TW/learn/basis"}],["link",{"rel":"alternate","hreflang":"en-US","href":"https://iztro.com/en_US/learn/basis"}],["link",{"rel":"alternate","hreflang":"ko-KR","href":"https://iztro.com/ko_KR/learn/basis"}],["link",{"rel":"alternate","hreflang":"ja-JP","href":"https://iztro.com/ja_JP/learn/basis"}],["link",{"rel":"alternate","hreflang":"vi-VN","href":"https://iztro.com/vi_VN/learn/basis"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://iztro.com/learn/basis"}],["meta",{"name":"robots","content":"max-image-preview:large"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"紫微研习社"}],["meta",{"property":"og:title","content":"자미두수 입문: 기초 지식과 용어 | 紫微研习社"}],["meta",{"property":"og:description","content":"자미두수가 무엇인지 소개하고 명반을 읽는 데 필요한 기초 개념과 용어를 설명합니다."}],["meta",{"property":"og:url","content":"https://iztro.com/ko_KR/learn/basis"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:locale:alternate","content":"zh_CN"}],["meta",{"property":"og:locale:alternate","content":"zh_TW"}],["meta",{"property":"og:locale:alternate","content":"en_US"}],["meta",{"property":"og:locale:alternate","content":"ja_JP"}],["meta",{"property":"og:locale:alternate","content":"vi_VN"}],["meta",{"property":"og:image","content":"https://iztro.com/static/home_img.png"}],["meta",{"property":"og:image:width","content":"850"}],["meta",{"property":"og:image:height","content":"850"}],["meta",{"property":"og:image:alt","content":"紫微研习社"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"자미두수 입문: 기초 지식과 용어 | 紫微研习社"}],["meta",{"name":"twitter:description","content":"자미두수가 무엇인지 소개하고 명반을 읽는 데 필요한 기초 개념과 용어를 설명합니다."}],["meta",{"name":"twitter:image","content":"https://iztro.com/static/home_img.png"}],["meta",{"name":"twitter:image:alt","content":"紫微研习社"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://iztro.com/ko_KR/learn/basis#webpage\\",\\"url\\":\\"https://iztro.com/ko_KR/learn/basis\\",\\"name\\":\\"자미두수 입문: 기초 지식과 용어 | 紫微研习社\\",\\"description\\":\\"자미두수가 무엇인지 소개하고 명반을 읽는 데 필요한 기초 개념과 용어를 설명합니다.\\",\\"inLanguage\\":\\"ko-KR\\",\\"isPartOf\\":{\\"@id\\":\\"https://iztro.com/#website\\"},\\"breadcrumb\\":{\\"@id\\":\\"https://iztro.com/ko_KR/learn/basis#breadcrumb\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"@id\\":\\"https://iztro.com/ko_KR/learn/basis#breadcrumb\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"紫微研习社\\",\\"item\\":\\"https://iztro.com/ko_KR/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"자미두수 입문: 기초 지식과 용어\\",\\"item\\":\\"https://iztro.com/ko_KR/learn/basis\\"}]}]}"]]},"headers":[],"relativePath":"ko_KR/learn/basis.md","filePath":"ko_KR/learn/basis.md"}'),n={name:"ko_KR/learn/basis.md"},g=Object.assign(n,{setup(h){return(s,m)=>(a(),r("div",null,[i,l(c),p]))}});export{k as __pageData,g as default};
